111	builder.Services.AddScoped<Maxx.Application.PremiosParticipacao.ContestacaoHandler>();
112	builder.Services.AddScoped<Maxx.Application.Perfil.BuscaDeAlunosHandler>();
113	builder.Services.AddScoped<Maxx.Application.Ranking.LeituraDoRankingHandler>();
114	builder.Services.AddScoped<Maxx.Application.Mural.PublicarAvisoHandler>();
115	builder.Services.AddScoped<Maxx.Application.Mural.MuralHandler>();
116	builder.Services.AddScoped<Maxx.Application.Notificacoes.NotificacoesHandler>();
117	builder.Services.AddScoped<Maxx.Application.Instituicao.AtosSobreOAlunoHandler>();
118	builder.Services.AddScoped<Maxx.Application.Instituicao.ConcessaoDiretaHandler>();
119	builder.Services.AddScoped<Maxx.Application.Instituicao.PurgaDaDemonstracaoHandler>();
120	
121	var app = builder.Build();
122	
123	if (isMigrate)
124	{
125	    await using var scope = app.Services.CreateAsyncScope();
126	    await scope.ServiceProvider.GetRequiredService<DatabaseMigrator>().MigrateAsync(CancellationToken.None);
127	    return 0;
128	}
129	
130	if (isSeed)
131	{
132	    if (args is not [_, var nomeDoPerfil, ..] || !Enum.TryParse<PerfilDeSeed>(nomeDoPerfil, ignoreCase: true, out var perfil)
133	        || !Enum.IsDefined(perfil))
134	    {
135	        await Console.Error.WriteLineAsync("Uso: Maxx.Api seed <base|demo>");
136	        return 2;
137	    }
138	
139	    await using var scope = app.Services.CreateAsyncScope();
140	    try
141	    {
142	        await scope.ServiceProvider.GetRequiredService<DatabaseSeeder>().SeedAsync(perfil, CancellationToken.None);
143	    }
144	    catch (SeedException ex)
145	    {
146	        // Dado recusado é resposta esperada, não falha do programa: sem pilha no log.
147	        await Console.Error.WriteLineAsync(ex.Message);
148	        return 1;
149	    }
150	
151	    return 0;
152	}
