154	if (isAnulacao)
155	{
156	    await using var scope = app.Services.CreateAsyncScope();
157	    return await ComandoDeAnulacao.ExecutarAsync(scope.ServiceProvider, args, Console.Out, Console.Error, CancellationToken.None);
158	}
