160	// Primeiro de tudo: o IP e o esquema reais vêm do Caddy, e só dele.
161	app.UseForwardedHeaders();
162	
163	// Um formato só de erro: ProblemDetails (RFC 9457).
164	app.UseExceptionHandler();
165	app.UseStatusCodePages();
