171	var api = app.MapGroup("/api");
172	api.MapHealthEndpoints();
173	
174	// Contrato versionado: só mudanças aditivas. Fechado por padrão: toda rota de /v1 exige
175	// login, e a pública diz isso com AllowAnonymous. No grupo, e não numa FallbackPolicy,
176	// porque a fallback vale também para pedido sem endpoint, e rota inexistente tem de
177	// continuar 404 (as rotas da demonstração desligada respondem igual a ela).
178	var v1 = api.MapGroup("/v1").RequireAuthorization();
179	v1.MapEuEndpoints();
180	v1.MapTermoDeUsoEndpoints();
181	v1.MapProfessorEndpoints();
182	v1.MapPremiosEndpoints();
183	v1.MapUploadEndpoints();
184	v1.MapPostEndpoints();
185	v1.MapSocialEndpoints();
186	v1.MapFeedEndpoints();
187	v1.MapPerfilEndpoints();
188	v1.MapEventoEndpoints();
189	v1.MapComprovacaoEndpoints();
190	v1.MapContestacaoEndpoints();
191	v1.MapAvisoEndpoints();
192	v1.MapNotificacaoEndpoints();
193	v1.MapRankingEndpoints();
194	v1.MapInstituicaoEndpoints();
195	v1.MapGroup("/auth").AllowAnonymous().MapCadastroEndpoints().MapLoginEndpoints().MapRecuperacaoEndpoints();
196	if (demonstracao)
197	{
198	    v1.MapDemonstracaoEndpoints();
199	}
200	
201	if (app.Environment.IsDevelopment())
202	{
203	    api.MapOpenApi("/openapi/{documentName}.json");
204	}
205	
206	await app.RunAsync();
207	return 0;
