1	using System.ComponentModel.DataAnnotations;
2	using Maxx.Api.Erros;
3	using Maxx.Api.LimiteDeTaxa;
4	using Maxx.Application.Autenticacao;
5	using Maxx.Application.Autenticacao.Login;
6	using Microsoft.AspNetCore.Http.HttpResults;
7	
8	namespace Maxx.Api.Autenticacao;
9	
10	// Login, renovação e logout (fluxos/01-login.md). Na web o refresh anda só em cookie; no
11	// nativo, só no corpo (SessaoHttp).
12	internal static partial class LoginEndpoints
13	{
14	    public static IEndpointRouteBuilder MapLoginEndpoints(this IEndpointRouteBuilder auth)
15	    {
16	        var grupo = auth.MapGroup("").WithTags("Autenticacao");
17	
18	        grupo.MapPost("/login", EntrarAsync)
19	            .WithName("Entrar")
20	            .ProducesValidationProblem()
21	            .ProducesProblem(StatusCodes.Status401Unauthorized)
22	            .ComLimiteDeTaxa(Limite.LoginPorIp, contexto => LimiteDeTaxaExtensions.Ip(contexto.HttpContext))
23	            .ComLimiteDeTaxa(
24	                Limite.LoginPorIdentificador,
25	                contexto => LimiteDeTaxaExtensions.Do<LoginRequest>(contexto, pedido => pedido.Identificador));
26	
27	        grupo.MapPost("/refresh", RenovarAsync)
28	            .WithName("RenovarSessao")
29	            .ProducesValidationProblem()
30	            .ProducesProblem(StatusCodes.Status401Unauthorized);
31	
32	        grupo.MapPost("/logout", SairAsync)
33	            .WithName("Sair")
34	            .ProducesValidationProblem();
35	
36	        return auth;
37	    }
38	
39	    private static async Task<Ok<SessaoResponse>> EntrarAsync(
40	        LoginRequest pedido, LoginHandler handler, HttpContext httpContext, CancellationToken cancellationToken)
41	    {
42	        var sessao = await handler.EntrarAsync(new Credenciais(pedido.Identificador, pedido.Senha), cancellationToken);
43	        return TypedResults.Ok(SessaoHttp.Escrever(httpContext, sessao));
44	    }
45	
46	    private static async Task<Results<Ok<SessaoResponse>, ProblemHttpResult>> RenovarAsync(
47	        RefreshRequest? pedido,
48	        RefreshHandler handler,
49	        HttpContext httpContext,
50	        ILoggerFactory loggers,
51	        CancellationToken cancellationToken)
52	    {
53	        var refresh = SessaoHttp.LerRefresh(httpContext.Request, pedido?.RefreshToken);
54	        var renovacao = refresh is null
55	            ? Renovacao.Recusada(RecusaDaRenovacao.Desconhecido)
56	            : await handler.RenovarAsync(refresh, cancellationToken);
57	
58	        if (renovacao.Sessao is { } sessao)
59	        {
60	            return TypedResults.Ok(SessaoHttp.Escrever(httpContext, sessao));
61	        }
62	
63	        var logger = loggers.CreateLogger(typeof(LoginEndpoints));
64	        if (renovacao.Recusa == RecusaDaRenovacao.ReusoDetectado)
65	        {
66	            LogReuso(logger, renovacao.FamiliaId);
67	        }
68	        else
69	        {
70	            LogRecusada(logger, renovacao.Recusa, renovacao.FamiliaId);
71	        }
72	
73	        SessaoHttp.Apagar(httpContext);
74	        return TypedResults.Problem(
75	            statusCode: StatusCodes.Status401Unauthorized,
76	            extensions: new Dictionary<string, object?> { [Erro.CampoCodigo] = CodigosDeRecusa.SessaoInvalida });
77	    }
78	
79	    // Sempre 204: refresh desconhecido ou família já revogada não muda a resposta.
80	    private static async Task<NoContent> SairAsync(
81	        RefreshRequest? pedido, LogoutHandler handler, HttpContext httpContext, CancellationToken cancellationToken)
82	    {
83	        if (SessaoHttp.LerRefresh(httpContext.Request, pedido?.RefreshToken) is { } refresh)
84	        {
85	            await handler.SairAsync(refresh, cancellationToken);
86	        }
87	
88	        SessaoHttp.Apagar(httpContext);
89	        return TypedResults.NoContent();
90	    }
91	
92	    [LoggerMessage(Level = LogLevel.Warning, Message = "Reuso de refresh: família {FamiliaId} revogada.")]
93	    private static partial void LogReuso(ILogger logger, Guid? familiaId);
94	
95	    [LoggerMessage(Level = LogLevel.Information, Message = "Renovação recusada ({Recusa}), família {FamiliaId}.")]
96	    private static partial void LogRecusada(ILogger logger, RecusaDaRenovacao? recusa, Guid? familiaId);
97	}
98	
99	// Identificador é o RA ou o e-mail. A senha só tem teto na borda: o Argon2id não recebe
100	// texto sem limite, e a política vale no cadastro, não no login.
101	public sealed record LoginRequest(
102	    [property: Required, StringLength(254)] string Identificador,
103	    [property: Required(AllowEmptyStrings = true), StringLength(512)] string Senha)
104	{
105	    public override string ToString() => "LoginRequest { }";
106	}
107	
108	// No nativo, o refresh vem aqui; na web o corpo pode faltar, porque ele vem do cookie.
109	public sealed record RefreshRequest([property: StringLength(128)] string? RefreshToken)
110	{
111	    public override string ToString() => "RefreshRequest { }";
112	}
