9	using Microsoft.AspNetCore.Authentication.JwtBearer;
10	using Microsoft.IdentityModel.Tokens;
11	
12	namespace Maxx.Api.Autenticacao;
13	
14	internal static class AutenticacaoServiceCollectionExtensions
15	{
16	    // exigirChave é falso só nos subcomandos (migrate, seed) e na geração do OpenAPI, que
17	    // não servem requisição. Fora de desenvolvimento, sem chave válida a API não sobe.
18	    public static WebApplicationBuilder AddAutenticacao(this WebApplicationBuilder builder, bool exigirChave)
19	    {
20	        var chave = LerChave(builder, exigirChave);
21	        builder.Services.AddSingleton(new ChaveDeAssinatura(chave));
22	        builder.Services.AddSingleton<IAccessTokenIssuer, JwtAccessTokenIssuer>();
23	        builder.Services.AddScoped<SessaoService>();
24	        builder.Services.AddScoped<SugestaoDeArroba>();
25	        builder.Services.AddScoped<TermoDeUsoHandler>();
26	        builder.Services.AddSingleton(LerDominiosAceitos(builder));
27	        builder.Services.AddScoped<CadastroHandler>();
28	        builder.Services.AddScoped<LoginHandler>();
29	        builder.Services.AddScoped<RefreshHandler>();
30	        builder.Services.AddScoped<LogoutHandler>();
31	        builder.Services.AddScoped<RecuperacaoHandler>();
32	        builder.AddEnvioDeEmail(exigirChave);
33	
34	        builder.Services.AddAuthentication(JwtBearerDefaults.AuthenticationScheme)
35	            .AddJwtBearer(options =>
36	            {
37	                // Claims com o nome que vieram (sub, papel), sem o mapeamento para os URIs
38	                // do WS-Federation.
39	                options.MapInboundClaims = false;
40	                options.TokenValidationParameters = new TokenValidationParameters
41	                {
42	                    ValidIssuer = JwtOptions.Emissor,
43	                    ValidAudience = JwtOptions.Audiencia,
44	                    IssuerSigningKey = chave,
45	                    ValidAlgorithms = [SecurityAlgorithms.HmacSha256],
46	                    ClockSkew = JwtOptions.Tolerancia,
47	                    NameClaimType = MaxxClaims.Sub,
48	                    RoleClaimType = MaxxClaims.Papel,
49	                };
50	            });
51	        builder.Services.AddAuthorization(Politicas.Configurar);
52	
53	        return builder;
54	    }
55	
56	    // O que o handler do e-mail de recuperação precisa da borda: SMTP e URL pública do app.
57	    // Na API e no worker: quem executa o trabalho é o worker, e a API e os testes de
58	    // integração montam os mesmos tipos de trabalho.
59	    public static IHostApplicationBuilder AddEnvioDeEmail(this IHostApplicationBuilder builder, bool exigirUrl)
60	    {
61	        builder.Services.AddSingleton<ILinkDoApp>(new LinkDoApp(LerUrlPublica(builder, exigirUrl)));
62	        builder.Services.Configure<EmailOptions>(builder.Configuration.GetSection(EmailOptions.Section));
63	        return builder;
64	    }
65	
66	    // Sem ela o link do e-mail de recuperação não teria para onde apontar: fora de
67	    // desenvolvimento nem a API nem o worker sobem.
68	    // Os domínios de e-mail aceitos no cadastro e na correção pela instituição (produto.md
69	    // 2.4), em Cadastro:DominiosDeEmailAceitos do appsettings.json: não é segredo, e a lista
70	    // é a mesma em todo ambiente. Vazia ou mal formada, nada sobe.
71	    private static DominiosDeEmailAceitos LerDominiosAceitos(IHostApplicationBuilder builder) =>
72	        new(builder.Configuration.GetSection("Cadastro:DominiosDeEmailAceitos").Get<string[]>() ?? []);
73	
74	    private static Uri LerUrlPublica(IHostApplicationBuilder builder, bool exigir)
75	    {
76	        var texto = builder.Configuration[$"{LinkDoApp.Section}:UrlPublica"];
77	        if (string.IsNullOrWhiteSpace(texto))
78	        {
79	            if (exigir && !builder.Environment.IsDevelopment())
80	            {
81	                throw new InvalidOperationException($"{LinkDoApp.Section}__UrlPublica não configurada: defina a URL pública do app.");
82	            }
83	
84	            texto = "http://localhost";
85	        }
86	
87	        if (!Uri.TryCreate(texto.Trim().TrimEnd('/') + "/", UriKind.Absolute, out var url) || url.Scheme is not ("http" or "https"))
88	        {
89	            throw new InvalidOperationException($"{LinkDoApp.Section}__UrlPublica inválida: {texto}.");
90	        }
91	
92	        return url;
93	    }
94	
95	    private static SymmetricSecurityKey LerChave(WebApplicationBuilder builder, bool exigirChave)
96	    {
97	        var texto = builder.Configuration.GetSection(JwtOptions.Section).Get<JwtOptions>()?.Chave;
98	
99	        if (string.IsNullOrWhiteSpace(texto))
100	        {
101	            if (exigirChave && !builder.Environment.IsDevelopment())
102	            {
103	                throw new InvalidOperationException(
104	                    $"{JwtOptions.Section}__Chave não configurada: defina uma chave base64 de ao menos {JwtOptions.TamanhoMinimoDaChaveEmBytes} bytes.");
105	            }
106	
107	            // Desenvolvimento sem chave: uma por processo, que some no restart. Nada
108	            // versionado, nem a chave de desenvolvimento.
109	            return new SymmetricSecurityKey(RandomNumberGenerator.GetBytes(JwtOptions.TamanhoMinimoDaChaveEmBytes));
110	        }
111	
112	        var bytes = new byte[texto.Length];
113	        if (!Convert.TryFromBase64String(texto.Trim(), bytes, out var escritos) || escritos < JwtOptions.TamanhoMinimoDaChaveEmBytes)
114	        {
115	            throw new InvalidOperationException(
116	                $"{JwtOptions.Section}__Chave inválida: tem de ser base64 de ao menos {JwtOptions.TamanhoMinimoDaChaveEmBytes} bytes.");
117	        }
118	
119	        return new SymmetricSecurityKey(bytes[..escritos]);
120	    }
121	}
