9	// Access token curto com sub e papéis, e nada mais: a lista de turmas do professor nunca
10	// entra no token (ADR 0006).
11	internal sealed class JwtAccessTokenIssuer(ChaveDeAssinatura chave, TimeProvider relogio) : IAccessTokenIssuer
12	{
13	    private readonly JsonWebTokenHandler _handler = new();
14	
15	    public AccessToken Issue(Usuario usuario)
16	    {
17	        ArgumentNullException.ThrowIfNull(usuario);
18	
19	        var agora = relogio.GetUtcNow();
20	        var expiraEm = agora + JwtOptions.Validade;
21	
22	        var claims = new Dictionary<string, object>
23	        {
24	            [MaxxClaims.Sub] = usuario.Id.ToString(),
25	            [MaxxClaims.Papel] = NomesDosPapeis(usuario.Papeis),
26	        };
27	
28	        var valor = _handler.CreateToken(new SecurityTokenDescriptor
29	        {
