9	
10	// O cadastro do aluno (produto.md 2.5): RA e e-mail na mesma linha do cadastro elegível,
11	// um RA uma conta, arroba único pelo prefixo. Professor e instituição não passam aqui.
12	public sealed class CadastroHandler(
13	    ICadastroElegivelRepository cadastros,
14	    IUsuarioRepository usuarios,
15	    ISenhaHasher senhas,
16	    SessaoService sessoes,
17	    SugestaoDeArroba sugestoes,
18	    TermoDeUsoHandler termos,
19	    IFilaDeTrabalhos fila,
20	    DominiosDeEmailAceitos dominios,
21	    IUnitOfWork unitOfWork,
22	    TimeProvider relogio)
23	{
24	    public async Task<Arroba> SugerirAsync(string ra, string email, CancellationToken cancellationToken)
25	    {
26	        var (cadastro, curso) = await BuscarSemContaAsync(ra, email, cancellationToken);
27	
28	        return new Arroba(
29	            await sugestoes.PrimeiroLivreAsync(cadastro.NomeCompleto, cancellationToken),
30	            Sufixo.Para(cadastro.Papeis, curso, exAluno: false));
31	    }
32	
33	    public async Task<bool> PrefixoDisponivelAsync(string ra, string email, string prefixo, CancellationToken cancellationToken)
34	    {
35	        Validar(() => PrefixoDeArroba.Validar(prefixo), CodigosDeRecusa.PrefixoInvalido);
36	        await BuscarSemContaAsync(ra, email, cancellationToken);
37	
38	        return (await usuarios.PrefixosOcupadosAsync([prefixo], cancellationToken)).Count == 0;
39	    }
40	
41	    public async Task<Sessao> CadastrarAsync(NovoCadastro pedido, CancellationToken cancellationToken)
42	    {
43	        ArgumentNullException.ThrowIfNull(pedido);
44	
45	        Validar(() => PoliticaDeSenha.Validar(pedido.Senha), CodigosDeRecusa.SenhaForaDaPolitica);
46	        Validar(() => PrefixoDeArroba.Validar(pedido.Prefixo), CodigosDeRecusa.PrefixoInvalido);
47	        Validar(() => Usuario.ValidarNomeDeExibicao(pedido.NomeDeExibicao), CodigosDeRecusa.NomeDeExibicaoInvalido);
48	
49	        var termo = await termos.ConferirAceiteAsync(pedido.VersaoDoTermo, cancellationToken);
50	        var (cadastro, curso) = await BuscarSemContaAsync(pedido.Ra, pedido.Email, cancellationToken);
51	        if ((await usuarios.PrefixosOcupadosAsync([pedido.Prefixo], cancellationToken)).Count > 0)
52	        {
53	            throw PrefixoIndisponivel();
54	        }
55	
56	        var usuario = Usuario.CadastrarAluno(
57	            cadastro, curso, pedido.NomeDeExibicao, pedido.Prefixo, senhas.Hash(pedido.Senha), relogio.GetUtcNow());
58	        usuario.AceitarTermo(termo, relogio.GetUtcNow());
59	        usuarios.Adicionar(usuario);
60	
61	        // Aluno novo muda o divisor da raridade (ADR 0005): o recálculo grava junto.
62	        fila.Enfileirar(new RecalcularRaridade());
63	        var sessao = sessoes.Abrir(usuario);
64	
65	        try
66	        {
67	            await unitOfWork.SalvarAsync(cancellationToken);
68	        }
69	        catch (ConflitoDeUnicidadeException conflito) when (conflito.Unicidade == Unicidade.ContaPorCadastro)
70	        {
71	            throw ContaExistente();
72	        }
73	        catch (ConflitoDeUnicidadeException conflito) when (conflito.Unicidade == Unicidade.Prefixo)
74	        {
75	            throw PrefixoIndisponivel();
76	        }
77	
78	        return sessao;
79	    }
80	
81	    // E-mail fora dos domínios aceitos (produto.md 2.4): recusado antes da base, com código
82	    // próprio, porque a lista não é segredo. Par que não está na mesma linha, RA de outra
83	    // pessoa, e-mail de professor: a mesma resposta, para não dizer qual dos dois errou. RA
84	    // que já tem conta vai para a recuperação de senha.
85	    private async Task<(CadastroElegivel Cadastro, Curso Curso)> BuscarSemContaAsync(
86	        string ra, string email, CancellationToken cancellationToken)
87	    {
88	        if (!dominios.Aceita(email.Trim()))
89	        {
90	            throw new RecusaException(TipoDeRecusa.Invalido, CodigosDeRecusa.EmailForaDaFaculdade);
91	        }
92	
93	        var encontrado = await cadastros.BuscarAlunoAsync(ra.Trim(), email.Trim(), cancellationToken)
94	            ?? throw new RecusaException(TipoDeRecusa.NaoEncontrado, CodigosDeRecusa.CadastroNaoEncontrado);
95	
96	        if (await usuarios.ExisteParaCadastroAsync(encontrado.Cadastro.Id, cancellationToken))
97	        {
98	            throw ContaExistente();
99	        }
100	
101	        return encontrado;
102	    }
103	
104	    private static RecusaException ContaExistente() => new(TipoDeRecusa.Conflito, CodigosDeRecusa.ContaExistente);
105	
106	    private static RecusaException PrefixoIndisponivel() => new(TipoDeRecusa.Conflito, CodigosDeRecusa.PrefixoIndisponivel);
107	
108	    // A regra continua no domínio; aqui só ganha o código que o cliente entende.
109	    private static void Validar(Action regra, string codigo)
110	    {
111	        try
112	        {
113	            regra();
114	        }
115	        catch (DomainException excecao)
116	        {
117	            throw new RecusaException(TipoDeRecusa.Invalido, codigo, excecao.Message);
118	        }
119	    }
120	}
