1	namespace Maxx.Domain.Identidade;
2	
3	// Uma sessão, de um login até o logout, o reuso ou a senha redefinida. Cada refresh usado
4	// é trocado por outro da mesma família; apresentar de novo um já trocado é sinal de roubo
5	// ou replay e derruba a família inteira (ADR 0006). O domínio só vê o hash do refresh:
6	// gerar o valor e calcular o hash é da infraestrutura.
7	public sealed class FamiliaDeSessao
8	{
9	    // Renovados a cada rotação, sem teto absoluto na fase 1 (decisoes/README.md).
10	    public static readonly TimeSpan ValidadeDoRefresh = TimeSpan.FromDays(30);
11	
12	    private readonly List<RefreshToken> _tokens = [];
13	
14	    // Para o EF Core materializar do banco.
15	    private FamiliaDeSessao()
16	    {
17	    }
18	
19	    private FamiliaDeSessao(Guid usuarioId, DateTimeOffset agora)
20	    {
21	        Id = Guid.CreateVersion7();
22	        UsuarioId = usuarioId;
23	        CriadaEm = agora;
24	    }
25	
26	    public Guid Id { get; private set; }
27	
28	    public Guid UsuarioId { get; private set; }
29	
30	    public DateTimeOffset CriadaEm { get; private set; }
31	
32	    public DateTimeOffset? RevogadaEm { get; private set; }
33	
34	    public MotivoDaRevogacao? MotivoDaRevogacao { get; private set; }
35	
36	    public bool EstaAtiva => RevogadaEm is null;
37	
38	    public IReadOnlyCollection<RefreshToken> Tokens => _tokens.AsReadOnly();
39	
40	    public static FamiliaDeSessao Abrir(Guid usuarioId, string hashDoRefresh, DateTimeOffset agora)
41	    {
42	        var familia = new FamiliaDeSessao(usuarioId, agora);
43	        familia.Emitir(hashDoRefresh, agora);
44	        return familia;
45	    }
46	
47	    // Família revogada vence tudo; depois o reuso, que revoga; depois a validade.
48	    public ResultadoDoRefresh Rotacionar(string hashApresentado, string hashDoNovo, DateTimeOffset agora)
49	    {
50	        var apresentado = _tokens.SingleOrDefault(token => token.Hash == hashApresentado)
51	            ?? throw new ArgumentException("O refresh apresentado não é desta família.", nameof(hashApresentado));
52	
53	        if (!EstaAtiva)
54	        {
55	            return ResultadoDoRefresh.FamiliaRevogada;
56	        }
57	
58	        if (apresentado.RotacionadoEm is not null)
59	        {
60	            Revogar(Identidade.MotivoDaRevogacao.Reuso, agora);
61	            return ResultadoDoRefresh.ReusoDetectado;
62	        }
63	
64	        if (agora > apresentado.ExpiraEm)
65	        {
66	            return ResultadoDoRefresh.Expirado;
67	        }
68	
69	        apresentado.MarcarRotacionado(agora);
70	        Emitir(hashDoNovo, agora);
71	        return ResultadoDoRefresh.Rotacionado;
72	    }
73	
74	    // Idempotente: a primeira revogação é a que fica registrada.
75	    public void Revogar(MotivoDaRevogacao motivo, DateTimeOffset agora)
76	    {
77	        if (!EstaAtiva)
78	        {
79	            return;
80	        }
81	
82	        RevogadaEm = agora;
83	        MotivoDaRevogacao = motivo;
84	    }
85	
86	    private void Emitir(string hash, DateTimeOffset agora)
87	    {
88	        hash = Texto.Obrigatorio(hash, "O hash do refresh");
89	        if (_tokens.Any(token => token.Hash == hash))
90	        {
91	            throw new ArgumentException("O hash do refresh novo já foi emitido nesta família.", nameof(hash));
92	        }
93	
94	        _tokens.Add(new RefreshToken(Id, hash, agora, agora + ValidadeDoRefresh));
95	    }
96	}
97	
98	public sealed class RefreshToken
99	{
100	    // Para o EF Core materializar do banco.
101	    private RefreshToken()
102	    {
103	        Hash = null!;
104	    }
105	
106	    internal RefreshToken(Guid familiaId, string hash, DateTimeOffset emitidoEm, DateTimeOffset expiraEm)
107	    {
108	        Id = Guid.CreateVersion7();
109	        FamiliaId = familiaId;
110	        Hash = hash;
111	        EmitidoEm = emitidoEm;
112	        ExpiraEm = expiraEm;
113	    }
114	
115	    public Guid Id { get; private set; }
116	
117	    public Guid FamiliaId { get; private set; }
118	
119	    // SHA-256 do valor entregue ao cliente. O valor em si nunca é guardado.
120	    public string Hash { get; private set; }
121	
122	    public DateTimeOffset EmitidoEm { get; private set; }
123	
124	    public DateTimeOffset ExpiraEm { get; private set; }
125	
126	    public DateTimeOffset? RotacionadoEm { get; private set; }
127	
128	    internal void MarcarRotacionado(DateTimeOffset agora) => RotacionadoEm = agora;
129	}
130	
131	public enum ResultadoDoRefresh
132	{
133	    Rotacionado,
134	    Expirado,
135	    FamiliaRevogada,
136	
137	    // A família acabou de ser revogada por este pedido.
138	    ReusoDetectado,
139	}
140	
141	public enum MotivoDaRevogacao
142	{
143	    Logout = 1,
144	    Reuso = 2,
145	    SenhaRedefinida = 3,
146	}
