1	using System.Globalization;
2	using System.Threading.RateLimiting;
3	using Maxx.Api.Erros;
4	
5	namespace Maxx.Api.LimiteDeTaxa;
6	
7	// Os limites de taxa (decisoes/README.md, Autenticação), por réplica e em memória, com os
8	// limitadores nativos de System.Threading.RateLimiting. Filtro de endpoint, e não policy
9	// do middleware, porque três das chaves estão no corpo (identificador, RA, e-mail), e o
10	// particionador do middleware roda antes de o corpo ser lido.
11	internal enum Limite
12	{
13	    LoginPorIdentificador,
14	    LoginPorIp,
15	    CadastroPorRa,
16	
17	    // Sugestão e disponibilidade de arroba, juntas: as duas respondem diferente para um par
18	    // de RA e e-mail que existe. 60 por minuto cabe na digitação porque o cliente do passo
19	    // 5 faz debounce antes de perguntar.
20	    ConsultaDeCadastroPorIp,
21	    RecuperacaoPorEmail,
22	
23	    // Alto de propósito: a banca inteira entra pelo mesmo celular roteado.
24	    RegistroDeDemonstracaoPorIp,
25	
26	    // Por pedido de assinatura, que cobre as duas derivadas de uma foto.
27	    UploadPorUsuario,
28	}
29	
30	internal sealed record RegraDeLimite(int Permitidos, TimeSpan Janela);
31	
32	internal sealed partial class LimitesDeTaxa : IDisposable
33	{
34	    // Chave mais longa que isto é truncada: o corpo ainda não passou pela validação.
35	    private const int _tamanhoMaximoDaChave = 256;
36	
37	    private readonly Dictionary<Limite, PartitionedRateLimiter<string>> _limitadores;
38	    private readonly ILogger<LimitesDeTaxa> _logger;
39	
40	    public LimitesDeTaxa(ILogger<LimitesDeTaxa> logger)
41	    {
42	        _logger = logger;
43	        _limitadores = Regras.ToDictionary(regra => regra.Key, regra => Criar(regra.Value));
44	    }
45	
46	    public static IReadOnlyDictionary<Limite, RegraDeLimite> Regras { get; } = new Dictionary<Limite, RegraDeLimite>
47	    {
48	        [Limite.LoginPorIdentificador] = new(5, TimeSpan.FromMinutes(1)),
49	        [Limite.LoginPorIp] = new(30, TimeSpan.FromMinutes(1)),
50	        [Limite.CadastroPorRa] = new(3, TimeSpan.FromMinutes(15)),
51	        [Limite.ConsultaDeCadastroPorIp] = new(60, TimeSpan.FromMinutes(1)),
52	        [Limite.RecuperacaoPorEmail] = new(3, TimeSpan.FromMinutes(15)),
53	        [Limite.RegistroDeDemonstracaoPorIp] = new(60, TimeSpan.FromHours(1)),
54	
55	        // Revisto no passo 7: um post ou uma foto de perfil por pedido, 30 por hora sobram.
56	        [Limite.UploadPorUsuario] = new(30, TimeSpan.FromHours(1)),
57	    };
58	
59	    public RateLimitLease Tentar(Limite limite, string chave)
60	    {
61	        var lease = _limitadores[limite].AttemptAcquire(chave.Length > _tamanhoMaximoDaChave ? chave[.._tamanhoMaximoDaChave] : chave);
62	        if (!lease.IsAcquired)
63	        {
64	            // A chave (e-mail, RA, identificador) é dado pessoal: o log leva só o limite.
65	            LogEstourado(_logger, limite);
66	        }
67	
68	        return lease;
69	    }
70	
71	    public void Dispose()
72	    {
73	        foreach (var limitador in _limitadores.Values)
74	        {
75	            limitador.Dispose();
76	        }
77	    }
78	
79	    // Janela fixa, sem fila: estourou, recusa na hora com o tempo até a janela virar.
80	    private static PartitionedRateLimiter<string> Criar(RegraDeLimite regra) =>
81	        PartitionedRateLimiter.Create<string, string>(chave => RateLimitPartition.GetFixedWindowLimiter(
82	            chave,
83	            _ => new FixedWindowRateLimiterOptions
84	            {
85	                PermitLimit = regra.Permitidos,
86	                Window = regra.Janela,
87	                QueueLimit = 0,
88	                AutoReplenishment = true,
89	            }));
90	
91	    [LoggerMessage(Level = LogLevel.Warning, Message = "Limite de taxa {Limite} estourado.")]
92	    private static partial void LogEstourado(ILogger logger, Limite limite);
93	}
94	
95	internal static class LimiteDeTaxaExtensions
96	{
97	    public static IServiceCollection AddLimitesDeTaxa(this IServiceCollection services) =>
98	        services.AddSingleton<LimitesDeTaxa>();
99	
100	    // O IP real: o ForwardedHeaders já trocou o do Caddy pelo do X-Forwarded-For, e só
101	    // quando o pedido veio da rede confiável (ProxyConfiavel).
102	    public static string Ip(HttpContext httpContext)
103	    {
104	        ArgumentNullException.ThrowIfNull(httpContext);
105	        return httpContext.Connection.RemoteIpAddress?.ToString() ?? "sem-ip";
106	    }
107	
108	    // Chave nula deixa passar: é corpo inválido, que a validação recusa logo depois.
109	    public static RouteHandlerBuilder ComLimiteDeTaxa(
110	        this RouteHandlerBuilder builder, Limite limite, Func<EndpointFilterInvocationContext, string?> chave)
111	    {
112	        ArgumentNullException.ThrowIfNull(builder);
113	        ArgumentNullException.ThrowIfNull(chave);
114	
115	        builder.AddEndpointFilter(async (contexto, proximo) =>
116	        {
117	            if (chave(contexto) is not { } valor)
118	            {
119	                return await proximo(contexto);
120	            }
121	
122	            using var lease = contexto.HttpContext.RequestServices.GetRequiredService<LimitesDeTaxa>().Tentar(limite, valor);
123	            if (lease.IsAcquired)
124	            {
125	                return await proximo(contexto);
126	            }
127	
128	            var espera = lease.TryGetMetadata(MetadataName.RetryAfter, out var retryAfter) ? retryAfter : LimitesDeTaxa.Regras[limite].Janela;
129	            contexto.HttpContext.Response.Headers.RetryAfter =
130	                Math.Max(1, (int)Math.Ceiling(espera.TotalSeconds)).ToString(CultureInfo.InvariantCulture);
131	            return TypedResults.Problem(
132	                statusCode: StatusCodes.Status429TooManyRequests,
133	                extensions: new Dictionary<string, object?> { [Erro.CampoCodigo] = "limite-de-taxa" });
134	        });
135	
136	        return builder.ProducesProblem(StatusCodes.Status429TooManyRequests);
137	    }
138	
139	    // Do argumento do tipo pedido, já desserializado.
140	    public static string? Do<TPedido>(EndpointFilterInvocationContext contexto, Func<TPedido, string?> campo)
141	    {
142	        ArgumentNullException.ThrowIfNull(contexto);
143	        ArgumentNullException.ThrowIfNull(campo);
144	        return contexto.Arguments.OfType<TPedido>().FirstOrDefault() is { } pedido
145	            ? campo(pedido)?.Trim().ToLowerInvariant()
146	            : null;
147	    }
148	}
