1	using Microsoft.AspNetCore.HttpOverrides;
2	
3	namespace Maxx.Api.Autenticacao;
4	
5	// X-Forwarded-For e X-Forwarded-Proto aceitos só de quem está na rede do Caddy. Sem a
6	// configuração, só do loopback (o padrão do ASP.NET Core): um cliente qualquer nunca
7	// escolhe o IP que o limite de taxa enxerga.
8	internal static class ProxyConfiavel
9	{
10	    public const string Section = "Proxy";
11	
12	    public static IServiceCollection AddProxyConfiavel(this IServiceCollection services, IConfiguration configuration)
13	    {
14	        var redes = configuration.GetSection($"{Section}:RedesConfiaveis").Get<string[]>() ?? [];
15	
16	        services.Configure<ForwardedHeadersOptions>(options =>
17	        {
18	            options.ForwardedHeaders = ForwardedHeaders.XForwardedFor | ForwardedHeaders.XForwardedProto;
19	
20	            // Um salto só: o Caddy. Ele acrescenta o IP de quem o chamou.
21	            options.ForwardLimit = 1;
22	            foreach (var rede in redes)
23	            {
24	                options.KnownIPNetworks.Add(System.Net.IPNetwork.Parse(rede));
25	            }
26	        });
27	
28	        return services;
29	    }
30	}
