11	// O pedido de envio de foto (ADR 0002): a API valida e assina, e o app envia as duas
12	// derivadas direto ao bucket. Os bytes nunca passam por aqui.
13	internal static class UploadEndpoints
14	{
15	    public static IEndpointRouteBuilder MapUploadEndpoints(this IEndpointRouteBuilder v1)
16	    {
17	        v1.MapPost("/uploads", PedirAsync)
18	            .WithName("PedirUpload")
19	            .WithTags("Fotos")
20	            .ComLimiteDeTaxa(Limite.UploadPorUsuario, contexto => contexto.HttpContext.User.FindFirstValue(MaxxClaims.Sub))
21	            .ProducesValidationProblem()
22	            .ProducesProblem(StatusCodes.Status401Unauthorized)
23	            .ProducesProblem(StatusCodes.Status403Forbidden);
24	
25	        return v1;
26	    }
