28	    private static async Task<Created<UploadResponse>> PedirAsync(
29	        PedidoDeUploadRequest pedido,
30	        ClaimsPrincipal principal,
31	        PedirUploadHandler handler,
32	        CancellationToken cancellationToken)
33	    {
34	        var finalidade = pedido.Finalidade switch
35	        {
36	            PedidoDeUploadRequest.FotoDePerfil => FinalidadeDoUpload.FotoDePerfil,
37	            PedidoDeUploadRequest.Aviso => FinalidadeDoUpload.Aviso,
38	            _ => FinalidadeDoUpload.Post,
39	        };
40	        var assinado = await handler.PedirAsync(
41	            UsuarioId(principal), finalidade, pedido.TipoDeConteudo, pedido.TamanhoDoFeed, pedido.TamanhoDaGrade, cancellationToken);
42	        return TypedResults.Created((string?)null, UploadResponse.De(assinado));
43	    }
