52	// O tipo e os tamanhos exatos, em bytes, das duas derivadas que o app já gerou: é o que vai
53	// preso na assinatura. Os limites são do domínio (UploadPendente); aqui só a forma. A
54	// finalidade "aviso" entrou no passo 10, só como acréscimo.
55	public sealed record PedidoDeUploadRequest(
56	    [property: Required, AllowedValues(PedidoDeUploadRequest.Post, PedidoDeUploadRequest.FotoDePerfil, PedidoDeUploadRequest.Aviso)]
57	    string Finalidade,
58	    [property: Required, StringLength(100)] string TipoDeConteudo,
59	    long TamanhoDoFeed,
60	    long TamanhoDaGrade)
61	{
62	    public const string Post = "post";
63	    public const string FotoDePerfil = "fotoDePerfil";
64	    public const string Aviso = "aviso";
65	}
