81	// depois de remover, não acha nada e termina. Confirmado antes, não toca em nada.
82	public sealed class LimparUploadAbandonadoHandler(
83	    IUploadPendenteRepository uploads,
84	    IArmazenamentoDeFotos armazenamento,
85	    IUnitOfWork unitOfWork) : ITrabalhoHandler<LimparUploadAbandonado>
86	{
87	    public async Task ExecutarAsync(LimparUploadAbandonado carga, CancellationToken cancellationToken)
88	    {
89	        ArgumentNullException.ThrowIfNull(carga);
90	
91	        var upload = await uploads.BuscarAsync(carga.UploadId, cancellationToken);
92	        if (upload is null || upload.EstaConfirmado)
93	        {
94	            return;
95	        }
96	
97	        uploads.Remover(upload);
98	        await unitOfWork.SalvarAsync(cancellationToken);
99	        await armazenamento.RemoverAsync(upload.Chaves, cancellationToken);
100	    }
101	}
102	
103	// Fotos que já foram usadas e deixaram de ser: post apagado ou removido, foto de perfil
104	// trocada. As chaves não são segredo, só endereço.
105	public sealed record RemoverFotos(IReadOnlyList<string> Chaves) : ICargaDeTrabalho
106	{
107	    public static string Tipo => "remover-fotos";
108	}
109	
110	// No worker. Remover chave que já não existe não é erro: o trabalho pode rodar de novo.
111	public sealed class RemoverFotosHandler(IArmazenamentoDeFotos armazenamento) : ITrabalhoHandler<RemoverFotos>
112	{
113	    public async Task ExecutarAsync(RemoverFotos carga, CancellationToken cancellationToken)
114	    {
115	        ArgumentNullException.ThrowIfNull(carga);
116	        await armazenamento.RemoverAsync(carga.Chaves, cancellationToken);
117	    }
118	}
