1	using System.Net;
2	using Amazon.Runtime;
3	using Amazon.S3;
4	using Amazon.S3.Model;
5	using Maxx.Application.Fotos;
6	using Microsoft.Extensions.Options;
7	
8	namespace Maxx.Infrastructure.Fotos;
9	
10	// O bucket pela API do S3, que o R2 e o emulador falam igual. Dois clientes: um assina
11	// com o endereço que o app alcança, sem ir à rede; o outro faz HEAD e remoção pelo
12	// endereço que a API alcança. Criados no primeiro uso: sem configuração, em
13	// desenvolvimento, a API sobe e só o que depende do bucket falha.
14	internal sealed class ArmazenamentoS3(IOptions<ArmazenamentoOptions> options) : IArmazenamentoDeFotos, IDisposable
15	{
16	    // Limite do DeleteObjects do S3.
17	    private const int _removidosPorPedido = 1000;
18	
19	    private readonly Lazy<Clientes> _clientes = new(() => Clientes.Criar(options.Value));
20	
21	    public EnvioAssinado AssinarEnvio(string chave, string tipoDeConteudo, long tamanho, DateTimeOffset expiraEm)
22	    {
23	        ArgumentException.ThrowIfNullOrWhiteSpace(chave);
24	        ArgumentException.ThrowIfNullOrWhiteSpace(tipoDeConteudo);
25	        ArgumentOutOfRangeException.ThrowIfNegativeOrZero(tamanho);
26	
27	        var clientes = _clientes.Value;
28	        var pedido = new GetPreSignedUrlRequest
29	        {
30	            BucketName = clientes.Bucket,
31	            Key = chave,
32	            Verb = HttpVerb.PUT,
33	            Expires = expiraEm.UtcDateTime,
34	            Protocol = clientes.ProtocoloPublico,
35	            ContentType = tipoDeConteudo,
36	        };
37	
38	        // Entra nos cabeçalhos assinados (X-Amz-SignedHeaders): o bucket recusa um corpo
39	        // de outro tamanho. É o que prende o tamanho, porque o R2 não aceita o POST com
40	        // política de content-length-range.
41	        pedido.Headers.ContentLength = tamanho;
42	
43	        var url = clientes.Assinatura.GetPreSignedURL(pedido);
44	        return new EnvioAssinado(chave, new Uri(url), tipoDeConteudo, tamanho, expiraEm);
45	    }
46	
47	    public async Task EnviarAsync(string chave, byte[] conteudo, string tipoDeConteudo, CancellationToken cancellationToken)
48	    {
49	        ArgumentException.ThrowIfNullOrWhiteSpace(chave);
50	        ArgumentNullException.ThrowIfNull(conteudo);
51	        var clientes = _clientes.Value;
52	        using var corpo = new MemoryStream(conteudo, writable: false);
53	        await clientes.Operacao.PutObjectAsync(
54	            new PutObjectRequest
55	            {
56	                BucketName = clientes.Bucket,
57	                Key = chave,
58	                InputStream = corpo,
59	                ContentType = tipoDeConteudo,
60	
61	                // O corpo assinado de uma vez, não em pedaços: o R2 recusa o
62	                // STREAMING-AWS4-HMAC-SHA256-PAYLOAD, que é o padrão do SDK e que o emulador
63	                // aceita. Provado só contra o R2 (VerificacaoDoR2Tests).
64	                UseChunkEncoding = false,
65	            },
66	            cancellationToken);
67	    }
68	
69	    public async Task<bool> ExisteAsync(string chave, CancellationToken cancellationToken)
70	    {
71	        ArgumentException.ThrowIfNullOrWhiteSpace(chave);
