219	// Remoção de post (produto.md 2.1 e 6.1). O autor apaga: o post sai do banco, com o que
220	// pendurar nele. A instituição remove: o post some para todos e fica quem removeu e quando.
221	// Nos dois casos a foto sai do bucket pela fila, porque a leitura é pública para quem tem
222	// o link (ADR 0002).
223	public sealed class RemoverPostHandler(
224	    IUsuarioRepository usuarios,
225	    IPostRepository posts,
226	    IPremioParticipacaoRepository premios,
227	    IFilaDeTrabalhos fila,
228	    IUnitOfWork unitOfWork,
229	    TimeProvider relogio)
230	{
231	    public async Task RemoverAsync(Guid quemId, Guid postId, CancellationToken cancellationToken)
232	    {
233	        var quem = await usuarios.BuscarAsync(quemId, cancellationToken)
234	            ?? throw new RecusaException(TipoDeRecusa.NaoAutorizado, CodigosDeRecusa.SessaoInvalida, $"Usuário {quemId} não existe.");
235	        var post = await posts.BuscarAsync(postId, cancellationToken);
236	        if (post is null || post.EstaRemovido)
237	        {
238	            throw new RecusaException(TipoDeRecusa.NaoEncontrado, CodigosDoPost.PostNaoEncontrado, $"Post {postId} não existe.");
239	        }
240	
241	        var modo = post.ModoDeRemocaoPor(quem);
242	
243	        // O post de reivindicação é a comprovação (produto.md 4.7). Enquanto o prêmio ainda pode
244	        // ser decidido, o autor não o apaga: a foto sairia do bucket junto, e a aprovação e a
245	        // contestação dependem dela. A instituição remove, e resolve o prêmio no mesmo ato,
246	        // porque não pode depender da fila para tirar do ar uma foto imprópria.
247	        if (modo != ModoDeRemocao.NaoPermitida
248	            && post.PremioParticipacaoId is { } premioId
249	            && await premios.BuscarAsync(premioId, cancellationToken) is { PrendeOPost: true } premio)
250	        {
