19	namespace Maxx.Api.Perfil;
20	
21	// Perfil, grade de posts, prêmios, busca e editar perfil (produto.md 6.4 e 6.5).
22	internal static class PerfilEndpoints
23	{
24	    // Seis linhas da grade de três colunas.
25	    public const int PostsPorPagina = 18;
26	
27	    public const int AlunosPorPagina = 20;
28	
29	    public static IEndpointRouteBuilder MapPerfilEndpoints(this IEndpointRouteBuilder v1)
30	    {
31	        var perfis = v1.MapGroup("/perfis/{usuarioId:guid}").WithTags("Perfil");
32	
33	        perfis.MapGet("/", PerfilAsync)
34	            .WithName("GetPerfil")
35	            .Produces<PerfilResponse>()
36	            .Produces(StatusCodes.Status304NotModified)
37	            .ProducesProblem(StatusCodes.Status404NotFound);
38	
39	        perfis.MapGet("/posts", PostsAsync)
40	            .WithName("GetPostsDoPerfil")
41	            .ProducesProblem(StatusCodes.Status400BadRequest)
42	            .ProducesProblem(StatusCodes.Status404NotFound);
43	
44	        perfis.MapGet("/premios", PremiosAsync)
45	            .WithName("GetPremiosDoPerfil")
46	            .ProducesProblem(StatusCodes.Status404NotFound);
47	
48	        var eu = v1.MapGroup("/eu/perfil").WithTags("Perfil");
49	
50	        eu.MapGet("/", MeuPerfilAsync)
51	            .WithName("GetMeuPerfil")
52	            .Produces<PerfilResponse>()
53	            .Produces(StatusCodes.Status304NotModified);
54	
55	        eu.MapPatch("/", EditarAsync)
56	            .WithName("EditarPerfil")
57	            .Produces<PerfilResponse>()
58	            .ProducesValidationProblem()
59	            .ProducesProblem(StatusCodes.Status404NotFound)
60	            .ProducesProblem(StatusCodes.Status409Conflict);
61	
62	        eu.MapGet("/disponibilidade", DisponibilidadeAsync)
63	            .WithName("GetDisponibilidadeDoMeuPrefixo")
64	            .ProducesProblem(StatusCodes.Status400BadRequest);
65	
66	        v1.MapGet("/cursos", CursosAsync)
67	            .WithName("GetCursos")
68	            .WithTags("Busca");
69	
70	        v1.MapGet("/busca/alunos", BuscarAsync)
71	            .WithName("BuscarAlunos")
72	            .WithTags("Busca")
73	            .ProducesProblem(StatusCodes.Status400BadRequest);
74	
75	        return v1;
76	    }
77	
78	    private static async Task<IResult> PerfilAsync(
79	        Guid usuarioId,
80	        HttpContext http,
81	        ClaimsPrincipal principal,
82	        IConsultaDePerfil consulta,
83	        IArmazenamentoDeFotos armazenamento,
84	        CancellationToken cancellationToken)
85	    {
86	        var perfil = await consulta.PerfilAsync(usuarioId, PostEndpoints.UsuarioId(principal), cancellationToken)
87	            ?? throw NaoEncontrado(usuarioId);
88	        return ComEtag(http, PerfilResponse.De(perfil, armazenamento));
89	    }
90	
91	    private static Task<IResult> MeuPerfilAsync(
92	        HttpContext http,
93	        ClaimsPrincipal principal,
94	        IConsultaDePerfil consulta,
95	        IArmazenamentoDeFotos armazenamento,
96	        CancellationToken cancellationToken) =>
97	        PerfilAsync(PostEndpoints.UsuarioId(principal), http, principal, consulta, armazenamento, cancellationToken);
98	
99	    private static async Task<Ok<PaginaDoFeedResponse>> PostsAsync(
100	        Guid usuarioId,
101	        string? cursor,
102	        ClaimsPrincipal principal,
103	        IConsultaDePerfil consulta,
104	        IConsultaDePosts posts,
105	        IArmazenamentoDeFotos armazenamento,
106	        CancellationToken cancellationToken)
107	    {
108	        var posicao = CursorDeTempo.Ler(cursor);
109	        var leitor = PostEndpoints.UsuarioId(principal);
110	        _ = await consulta.PerfilAsync(usuarioId, leitor, cancellationToken) ?? throw NaoEncontrado(usuarioId);
111	
112	        var pagina = await consulta.PostsAsync(usuarioId, posicao, PostsPorPagina, cancellationToken);
113	        var lidos = await posts.PostsAsync(pagina.Itens, leitor, cancellationToken);
114	        return TypedResults.Ok(new PaginaDoFeedResponse(
115	            [.. pagina.Itens.Where(lidos.ContainsKey).Select(id => PostResponse.De(lidos[id], armazenamento))], pagina.Proximo));
116	    }
117	
118	    // Só os prêmios obtidos: os faltantes e o progresso são do próprio aluno, em /v1/eu/premios.
119	    private static async Task<Ok<PremiosDoAlunoResponse>> PremiosAsync(
120	        Guid usuarioId, IConsultaDePremios consulta, CancellationToken cancellationToken)
121	    {
122	        var premios = await consulta.DoAlunoAsync(usuarioId, cancellationToken) ?? throw NaoEncontrado(usuarioId);
123	        return TypedResults.Ok(PremiosEndpoints.Mapear(premios, soObtidos: true));
124	    }
125	
126	    private static async Task<IResult> EditarAsync(
127	        EditarPerfilRequest pedido,
128	        HttpContext http,
129	        ClaimsPrincipal principal,
130	        EditarPerfilHandler handler,
131	        IConsultaDePerfil consulta,
132	        IArmazenamentoDeFotos armazenamento,
133	        CancellationToken cancellationToken)
134	    {
135	        var eu = PostEndpoints.UsuarioId(principal);
136	        await handler.EditarAsync(eu, pedido.NomeDeExibicao, pedido.Prefixo, pedido.FotoUploadId, pedido.RemoverFoto ?? false, cancellationToken);
137	        var perfil = await consulta.PerfilAsync(eu, eu, cancellationToken)
138	            ?? throw new RecusaException(TipoDeRecusa.NaoEncontrado, CodigosSociais.UsuarioNaoEncontrado, "Conta sem perfil social.");
139	        return ComEtag(http, PerfilResponse.De(perfil, armazenamento), aceitar304: false);
140	    }
141	
142	    private static async Task<Ok<DisponibilidadeDoPrefixoResponse>> DisponibilidadeAsync(
143	        [Required] string prefixo, ClaimsPrincipal principal, EditarPerfilHandler handler, CancellationToken cancellationToken) =>
144	        TypedResults.Ok(new DisponibilidadeDoPrefixoResponse(
145	            await handler.PrefixoDisponivelAsync(PostEndpoints.UsuarioId(principal), prefixo, cancellationToken)));
146	
147	    private static async Task<Ok<IReadOnlyList<CursoResponse>>> CursosAsync(IConsultaDePerfil consulta, CancellationToken cancellationToken) =>
148	        TypedResults.Ok<IReadOnlyList<CursoResponse>>([.. (await consulta.CursosAsync(cancellationToken)).Select(curso => new CursoResponse(curso.Sigla, curso.Nome, curso.DuracaoEmSemestres, curso.Id))]);
149	
150	    private static async Task<Ok<PaginaDeAlunosResponse>> BuscarAsync(
151	        string? termo,
152	        string? curso,
153	        [Range(1, int.MaxValue)] int? semestre,
154	        string? cursor,
155	        ClaimsPrincipal principal,
156	        BuscaDeAlunosHandler handler,
157	        IArmazenamentoDeFotos armazenamento,
158	        CancellationToken cancellationToken)
159	    {
160	        var pagina = await handler.BuscarAsync(PostEndpoints.UsuarioId(principal), termo, curso, semestre, cursor, AlunosPorPagina, cancellationToken);
161	        return TypedResults.Ok(new PaginaDeAlunosResponse(
162	            [.. pagina.Itens.Select(aluno => new AlunoEncontradoResponse(
163	                aluno.Id,
164	                aluno.NomeDeExibicao,
165	                aluno.Arroba,
166	                aluno.Curso,
167	                aluno.Semestre,
168	                aluno.ExAluno,
169	                PostResponse.Leitura(armazenamento, aluno.ChaveDaFotoDaGrade),
170	                aluno.EuSigo))],
171	            pagina.Proximo));
