1	using Maxx.Application.Autenticacao;
2	using Maxx.Application.Paginacao;
3	using Maxx.Domain.Mural;
4	
5	namespace Maxx.Application.Mural;
6	
7	// Quem lê o mural e o que o define (produto.md 7): os vínculos vêm do banco a cada pedido,
8	// nunca do token. Curso é o atual, do cadastro; o professor não tem nenhum dos dois.
9	public sealed record LeitorDoMural(Guid Id, Guid CadastroId, Guid? CursoId, bool Instituicao);
10	
11	// O aviso como o app mostra: o autor (nome e se é a instituição, que o app mostra como
12	// "UniMax"), as matérias das turmas ou as siglas dos cursos, e se o leitor já o leu.
13	public sealed record AvisoLido(
14	    Guid Id,
15	    EscopoDoAviso Escopo,
16	    string Titulo,
17	    string Texto,
18	    string? ChaveDaFotoDoFeed,
19	    string? ChaveDaFotoDaGrade,
20	    DateTimeOffset PublicadoEm,
21	    AutorDoAviso Autor,
22	    IReadOnlyList<string> Materias,
23	    IReadOnlyList<string> Cursos,
24	    bool Lido);
25	
26	public sealed record AutorDoAviso(Guid Id, string NomeDeExibicao, bool Instituicao);
27	
28	// O mural de cada um, numa regra só (passo 10, pergunta 3), que vale para a lista, para o
29	// aviso aberto pelo link, para a leitura e para o "Ler todos":
30	//
31	// - A instituição vê tudo.
32	// - Os outros veem os avisos da faculdade, os que publicaram, os dos cursos em que estão
33	//   (o curso atual) e os das turmas em que têm matrícula, de qualquer semestre. O
34	//   ex-aluno lê pelos mesmos vínculos; o professor, que não tem curso nem matrícula, vê a
35	//   faculdade e os dele.
36	public interface IConsultaDoMural
37	{
38	    // Nulo para quem não existe mais (token de conta purgada).
39	    Task<LeitorDoMural?> LeitorAsync(Guid usuarioId, CancellationToken cancellationToken);
40	
41	    // Do mais novo ao mais antigo, por cursor (publicado_em, id). Com escopo, só ele; com
42	    // autor, só os desse autor (o perfil do professor).
43	    Task<Pagina<AvisoLido>> MuralAsync(
44	        LeitorDoMural leitor,
45	        EscopoDoAviso? escopo,
46	        Guid? autorId,
47	        PosicaoNoTempo? depoisDe,
48	        int limite,
49	        CancellationToken cancellationToken);
50	
51	    // Nulo para o aviso que não existe e para o que o leitor não vê.
52	    Task<AvisoLido?> AvisoAsync(LeitorDoMural leitor, Guid avisoId, CancellationToken cancellationToken);
53	
54	    // Se há aviso no mural do leitor que ele ainda não leu: a bolinha da aba Mural.
55	    Task<bool> TemNaoLidoAsync(LeitorDoMural leitor, CancellationToken cancellationToken);
56	
57	    // Registra a leitura dos avisos visíveis ao leitor entre os pedidos (todos, sem ids) e
58	    // marca como lida a notificação de aviso novo de cada um. Idempotente: a leitura antiga
59	    // fica com o instante dela. Devolve quantas leituras novas gravou.
60	    Task<int> RegistrarLeituraAsync(
61	        LeitorDoMural leitor, IReadOnlyCollection<Guid>? avisoIds, DateTimeOffset agora, CancellationToken cancellationToken);
62	}
63	
64	// Ler o mural, abrir um aviso, registrar a leitura e o "Ler todos" (produto.md 7).
65	public sealed class MuralHandler(IConsultaDoMural consulta, TimeProvider relogio)
66	{
67	    public async Task<Pagina<AvisoLido>> MuralAsync(
68	        Guid leitorId, EscopoDoAviso? escopo, Guid? autorId, string? cursor, int limite, CancellationToken cancellationToken)
69	    {
70	        var posicao = CursorDeTempo.Ler(cursor);
71	        var leitor = await LeitorAsync(leitorId, cancellationToken);
72	        return await consulta.MuralAsync(leitor, escopo, autorId, posicao, limite, cancellationToken);
73	    }
74	
75	    public async Task<AvisoLido> AvisoAsync(Guid leitorId, Guid avisoId, CancellationToken cancellationToken)
76	    {
77	        var leitor = await LeitorAsync(leitorId, cancellationToken);
78	        return await consulta.AvisoAsync(leitor, avisoId, cancellationToken) ?? throw NaoEncontrado(avisoId);
79	    }
80	
81	    // Abrir o aviso registra a leitura (passo 10, pergunta 2). O que o leitor não vê é 404,
82	    // como o que não existe: ninguém descobre aviso alheio pelo id.
83	    public async Task LerAsync(Guid leitorId, Guid avisoId, CancellationToken cancellationToken)
84	    {
85	        var leitor = await LeitorAsync(leitorId, cancellationToken);
86	        _ = await consulta.AvisoAsync(leitor, avisoId, cancellationToken) ?? throw NaoEncontrado(avisoId);
87	        await consulta.RegistrarLeituraAsync(leitor, [avisoId], relogio.GetUtcNow(), cancellationToken);
88	    }
89	
90	    // "Ler todos": só o que a pessoa vê.
91	    public async Task<int> LerTodosAsync(Guid leitorId, CancellationToken cancellationToken)
92	    {
93	        var leitor = await LeitorAsync(leitorId, cancellationToken);
94	        return await consulta.RegistrarLeituraAsync(leitor, null, relogio.GetUtcNow(), cancellationToken);
95	    }
96	
97	    private async Task<LeitorDoMural> LeitorAsync(Guid leitorId, CancellationToken cancellationToken) =>
98	        await consulta.LeitorAsync(leitorId, cancellationToken)
99	        ?? throw new RecusaException(TipoDeRecusa.NaoAutorizado, CodigosDeRecusa.SessaoInvalida, $"Usuário {leitorId} não existe.");
100	
101	    private static RecusaException NaoEncontrado(Guid avisoId) =>
102	        new(TipoDeRecusa.NaoEncontrado, CodigosDoMural.AvisoNaoEncontrado, $"Aviso {avisoId} inexistente ou fora do mural do leitor.");
103	}
