174	    // ETag do conteúdo, com 304 quando o app já tem a versão (decisoes/README.md, Cache). A
175	    // resposta depende de quem pede (RA, "eu sigo"): private, nunca em cache compartilhado.
176	    internal static IResult ComEtag<T>(HttpContext http, T corpo, bool aceitar304 = true)
177	    {
178	        var opcoes = http.RequestServices.GetRequiredService<IOptions<Microsoft.AspNetCore.Http.Json.JsonOptions>>().Value.SerializerOptions;
179	        var etag = $"W/\"{Convert.ToBase64String(SHA256.HashData(JsonSerializer.SerializeToUtf8Bytes(corpo, opcoes)))[..22]}\"";
180	        http.Response.Headers.ETag = etag;
181	        http.Response.Headers.CacheControl = "private, no-cache";
182	
183	        return aceitar304 && http.Request.Headers.IfNoneMatch.Any(valor => valor == etag)
184	            ? TypedResults.StatusCode(StatusCodes.Status304NotModified)
185	            : TypedResults.Ok(corpo);
186	    }
