117	// Os trabalhos que a decisão enfileira, na mesma transação.
118	public sealed record NotificarComprovacaoAprovada(Guid PremioId) : ICargaDeTrabalho
119	{
120	    public static string Tipo => "notificar-comprovacao-aprovada";
121	}
122	
123	public sealed record NotificarComprovacaoReprovada(Guid PremioId) : ICargaDeTrabalho
124	{
125	    public static string Tipo => "notificar-comprovacao-reprovada";
126	}
127	
128	// A concessão direta da instituição (passo 12): o prêmio já nasce aprovado.
129	public sealed record NotificarPremioConcedido(Guid PremioId) : ICargaDeTrabalho
130	{
131	    public static string Tipo => "notificar-premio-concedido";
132	}
133	
134	// Agendado para o fim da janela de contestação (fluxos/04-contestacao.md).
135	public sealed record TornarPremioDefinitivo(Guid PremioId) : ICargaDeTrabalho
136	{
137	    public static string Tipo => "tornar-premio-definitivo";
138	}
139	
140	// No worker: grava a notificação de comprovação decidida (produto.md 8) e a do prêmio
141	// concedido direto pela instituição (passo 12). Uma por prêmio e
142	// tipo, mesmo que o trabalho rode de novo; nenhuma para o prêmio que a purga já levou.
143	public sealed class NotificarComprovacaoHandler(
144	    IPremioParticipacaoRepository premios,
145	    INotificacaoRepository notificacoes,
146	    IUnitOfWork unitOfWork,
147	    TimeProvider relogio)
148	    : ITrabalhoHandler<NotificarComprovacaoAprovada>, ITrabalhoHandler<NotificarComprovacaoReprovada>, ITrabalhoHandler<NotificarPremioConcedido>
149	{
150	    public Task ExecutarAsync(NotificarPremioConcedido carga, CancellationToken cancellationToken)
151	    {
152	        ArgumentNullException.ThrowIfNull(carga);
153	        return NotificarAsync(carga.PremioId, TipoDeNotificacao.PremioConcedido, Notificacao.PremioConcedido, cancellationToken);
154	    }
155	
156	    public Task ExecutarAsync(NotificarComprovacaoAprovada carga, CancellationToken cancellationToken)
157	    {
158	        ArgumentNullException.ThrowIfNull(carga);
159	        return NotificarAsync(carga.PremioId, TipoDeNotificacao.ComprovacaoAprovada, Notificacao.ComprovacaoAprovada, cancellationToken);
160	    }
161	
162	    public Task ExecutarAsync(NotificarComprovacaoReprovada carga, CancellationToken cancellationToken)
163	    {
164	        ArgumentNullException.ThrowIfNull(carga);
165	        return NotificarAsync(carga.PremioId, TipoDeNotificacao.ComprovacaoReprovada, Notificacao.ComprovacaoReprovada, cancellationToken);
166	    }
167	
168	    private async Task NotificarAsync(
169	        Guid premioId,
170	        TipoDeNotificacao tipo,
171	        Func<PremioParticipacao, DateTimeOffset, Notificacao> criar,
172	        CancellationToken cancellationToken)
173	    {
174	        var premio = await premios.BuscarAsync(premioId, cancellationToken);
175	        if (premio is null || await notificacoes.ExisteAsync(premio.AlunoId, tipo, premio.Id, cancellationToken))
176	        {
177	            return;
178	        }
179	
180	        notificacoes.Adicionar(criar(premio, relogio.GetUtcNow()));
181	        await unitOfWork.SalvarAsync(cancellationToken);
182	    }
183	}
184	
185	// No worker, no fim da janela: o prêmio ainda válido fica definitivo (produto.md 4.7). O
186	// contestado, decidido ou apagado pela purga fica como está. Se o trabalho chegar antes do
187	// fim da janela, volta para a fila no instante certo, em vez de se perder.
188	public sealed class TornarPremioDefinitivoHandler(
189	    IPremioParticipacaoRepository premios,
190	    IFilaDeTrabalhos fila,
191	    IUnitOfWork unitOfWork,
192	    TimeProvider relogio) : ITrabalhoHandler<TornarPremioDefinitivo>
193	{
194	    public async Task ExecutarAsync(TornarPremioDefinitivo carga, CancellationToken cancellationToken)
195	    {
196	        ArgumentNullException.ThrowIfNull(carga);
197	
198	        var premio = await premios.BuscarAsync(carga.PremioId, cancellationToken);
199	        if (premio is not { Estado: EstadoDoPremioParticipacao.Valido })
200	        {
201	            return;
202	        }
203	
204	        if (premio.TornarDefinitivoSeAJanelaFechou(relogio.GetUtcNow()))
205	        {
206	            // Definitivo, o prêmio passa a contar para conquista (regras-conquista.md 3).
207	            fila.Enfileirar(ReavaliarConquistas.PeloPremio(premio.AlunoId, premio.Id));
208	        }
209	        else
210	        {
211	            fila.Enfileirar(carga, premio.FimDaJanela);
212	        }
213	
214	        await unitOfWork.SalvarAsync(cancellationToken);
215	    }
216	}
