43	        {
44	            throw resultado.Recusa switch
45	            {
46	                RecusaDaContestacao.NaoContestavel => new RecusaException(
47	                    TipoDeRecusa.Conflito, CodigosDoPremioParticipacao.PremioNaoContestavel, $"Prêmio {premioId} não aprovado."),
48	                RecusaDaContestacao.JaContestado => JaContestado(premioId),
49	                RecusaDaContestacao.ForaDaJanela => new RecusaException(
50	                    TipoDeRecusa.Conflito, CodigosDoPremioParticipacao.ForaDaJanelaDeContestacao, $"Janela do prêmio {premioId} fechada."),
51	                RecusaDaContestacao.MotivoInvalido => MotivoInvalido(),
52	                _ => new InvalidOperationException($"Recusa sem tratamento: {resultado.Recusa}."),
53	            };
54	        }
55	
56	        premios.Adicionar(contestacao);
57	        fila.Enfileirar(new NotificarContestacaoAberta(premio.Id));
58	        fila.PedirRecalculos();
59	        try
60	        {
61	            await unitOfWork.SalvarAsync(cancellationToken);
62	        }
63	        catch (ConflitoDeUnicidadeException conflito) when (conflito.Unicidade == Unicidade.ContestacaoPorPremio)
64	        {
65	            throw JaContestado(premioId);
66	        }
67	        catch (ConflitoDeConcorrenciaException)
68	        {
69	            // Outro ato mudou o prêmio entre a leitura e a gravação: outra contestação, ou a
70	            // instituição removendo o post.
71	            throw JaContestado(premioId);
72	        }
73	
74	        return contestacao;
75	    }
76	
77	    // Confirmado: definitivo na hora, volta a pontuar, janela encerrada.
78	    public async Task ConfirmarAsync(Guid quemId, Guid contestacaoId, CancellationToken cancellationToken)
79	    {
80	        var (quem, contestacao, premio) = await CarregarAsync(quemId, contestacaoId, cancellationToken);
81	
82	        if (premio.Confirmar(contestacao, quem, relogio.GetUtcNow()) is { } recusa)
83	        {
84	            throw Recusa(recusa, contestacaoId);
85	        }
86	
87	        fila.Enfileirar(new NotificarDecisaoDeContestacao(premio.Id));
88	        fila.Enfileirar(ReavaliarConquistas.PeloPremio(premio.AlunoId, premio.Id));
89	        fila.PedirRecalculos();
90	        await SalvarDecisaoAsync(contestacaoId, cancellationToken);
91	    }
92	
93	    // Revogado, com motivo: sai da pontuação, fica no histórico, e o post perde o vínculo.
94	    public async Task RevogarAsync(Guid quemId, Guid contestacaoId, string? motivo, CancellationToken cancellationToken)
95	    {
96	        var (quem, contestacao, premio) = await CarregarAsync(quemId, contestacaoId, cancellationToken);
97	
98	        if (premio.Revogar(quem, motivo, contestacao, relogio.GetUtcNow()) is { } recusa)
99	        {
100	            throw Recusa(recusa, contestacaoId);
101	        }
102	
103	        await DesvincularPostsAsync(posts, premio, cancellationToken);
104	        fila.Enfileirar(new NotificarDecisaoDeContestacao(premio.Id));
105	        fila.PedirRecalculos();
106	        await SalvarDecisaoAsync(contestacaoId, cancellationToken);
107	    }
108	
109	    // O post do prêmio revogado ou reprovado fica como post comum; se era só o prêmio, sem
110	    // foto e sem legenda, sai, porque post vazio não existe (produto.md 4.7).
111	    internal static async Task DesvincularPostsAsync(IPostRepository posts, PremioParticipacao premio, CancellationToken cancellationToken)
112	    {
113	        foreach (var post in await posts.DoPremioParticipacaoAsync(premio.Id, cancellationToken))
114	        {
115	            if (post.FicariaVazioSemPremio)
116	            {
117	                posts.Apagar(post);
118	            }
119	            else
120	            {
121	                post.DesvincularPremio();
122	            }
123	        }
124	    }
125	
126	    private async Task<(Usuario Quem, Contestacao Contestacao, PremioParticipacao Premio)> CarregarAsync(
127	        Guid quemId, Guid contestacaoId, CancellationToken cancellationToken)
128	    {
129	        var quem = await QuemAsync(quemId, cancellationToken);
130	        if (!quem.Papeis.HasFlag(Papeis.Instituicao))
131	        {
132	            throw new RecusaException(TipoDeRecusa.Proibido, CodigosDaMedalha.ForaDoEscopo, $"{quemId} não decide contestação.");
133	        }
134	
135	        var contestacao = await premios.ContestacaoAsync(contestacaoId, cancellationToken)
136	            ?? throw new RecusaException(
137	                TipoDeRecusa.NaoEncontrado, CodigosDoPremioParticipacao.ContestacaoNaoEncontrada, $"Contestação {contestacaoId} não existe.");
138	        var premio = await premios.BuscarAsync(contestacao.PremioParticipacaoId, cancellationToken)
139	            ?? throw new InvalidOperationException($"A contestação {contestacaoId} não tem prêmio.");
140	        return (quem, contestacao, premio);
141	    }
142	
143	    private async Task<Usuario> QuemAsync(Guid quemId, CancellationToken cancellationToken) =>
144	        await usuarios.BuscarAsync(quemId, cancellationToken)
145	            ?? throw new RecusaException(TipoDeRecusa.NaoAutorizado, CodigosDeRecusa.SessaoInvalida, $"Usuário {quemId} não existe.");
146	
147	    private async Task SalvarDecisaoAsync(Guid contestacaoId, CancellationToken cancellationToken)
148	    {
149	        try
150	        {
151	            await unitOfWork.SalvarAsync(cancellationToken);
152	        }
153	        catch (ConflitoDeConcorrenciaException)
154	        {
155	            // Outra decisão gravou primeiro.
156	            throw Recusa(RecusaDaDecisao.JaDecidida, contestacaoId);
157	        }
158	    }
159	
160	    private static RecusaException Recusa(RecusaDaDecisao recusa, Guid contestacaoId) => recusa switch
161	    {
162	        RecusaDaDecisao.JaDecidida => new(
163	            TipoDeRecusa.Conflito, CodigosDoPremioParticipacao.ContestacaoJaDecidida, $"Contestação {contestacaoId} já decidida."),
164	        RecusaDaDecisao.MotivoInvalido => MotivoInvalido(),
165	        _ => throw new ArgumentOutOfRangeException(nameof(recusa), recusa, null),
166	    };
167	
168	    private static RecusaException PremioNaoEncontrado(Guid premioId) =>
169	        new(TipoDeRecusa.NaoEncontrado, CodigosDoPremioParticipacao.PremioNaoEncontrado, $"Prêmio {premioId} não existe.");
170	
171	    private static RecusaException JaContestado(Guid premioId) =>
172	        new(TipoDeRecusa.Conflito, CodigosDoPremioParticipacao.PremioJaContestado, $"Prêmio {premioId} já contestado.");
173	
174	    private static RecusaException MotivoInvalido() =>
175	        new(TipoDeRecusa.Invalido, CodigosDoPremioParticipacao.MotivoInvalido, "Motivo vazio ou acima do limite.");
176	}
177	
178	// A remoção do post pela instituição resolve o prêmio no mesmo ato (decisão do passo 8): a
179	// instituição não pode depender da fila para tirar do ar uma foto imprópria. Pendente,
180	// reprova; válido, revoga; em averiguação, decide a contestação revogando. Sempre com o
181	// motivo de Motivo.RemovidoPelaInstituicao, e depois o post sai.
182	public static class RemocaoPelaInstituicao
183	{
184	    public static async Task ResolverAsync(
185	        PremioParticipacao premio,
186	        Usuario instituicao,
187	        IPremioParticipacaoRepository premios,
188	        IPostRepository posts,
189	        IFilaDeTrabalhos fila,
190	        DateTimeOffset agora,
191	        CancellationToken cancellationToken)
192	    {
193	        ArgumentNullException.ThrowIfNull(premio);
194	        ArgumentNullException.ThrowIfNull(premios);
195	        ArgumentNullException.ThrowIfNull(fila);
196	
197	        RecusaDaDecisao? recusa;
198	        switch (premio.Estado)
199	        {
200	            case EstadoDoPremioParticipacao.Reivindicado:
201	                recusa = premio.Reprovar(instituicao, Motivo.RemovidoPelaInstituicao, agora);
202	                fila.Enfileirar(new NotificarComprovacaoReprovada(premio.Id));
203	                break;
204	            case EstadoDoPremioParticipacao.Valido:
205	                recusa = premio.Revogar(instituicao, Motivo.RemovidoPelaInstituicao, null, agora);
206	                fila.Enfileirar(new NotificarPremioRevogado(premio.Id));
207	                fila.PedirRecalculos();
208	                break;
209	            case EstadoDoPremioParticipacao.EmAveriguacao:
210	                var contestacao = await premios.ContestacaoDoPremioAsync(premio.Id, cancellationToken)
211	                    ?? throw new InvalidOperationException($"O prêmio {premio.Id} está em averiguação sem contestação.");
212	                recusa = premio.Revogar(instituicao, Motivo.RemovidoPelaInstituicao, contestacao, agora);
213	                fila.Enfileirar(new NotificarDecisaoDeContestacao(premio.Id));
214	                fila.PedirRecalculos();
215	                break;
216	            default:
217	                return;
218	        }
219	
220	        if (recusa is not null)
221	        {
222	            throw new InvalidOperationException($"A instituição não resolveu o prêmio {premio.Id}: {recusa}.");
223	        }
224	
225	        await ContestacaoHandler.DesvincularPostsAsync(posts, premio, cancellationToken);
226	    }
227	}
228	
229	public sealed record NotificarContestacaoAberta(Guid PremioId) : ICargaDeTrabalho
230	{
231	    public static string Tipo => "notificar-contestacao-aberta";
232	}
233	
234	public sealed record NotificarDecisaoDeContestacao(Guid PremioId) : ICargaDeTrabalho
235	{
236	    public static string Tipo => "notificar-decisao-de-contestacao";
237	}
238	
239	public sealed record NotificarPremioRevogado(Guid PremioId) : ICargaDeTrabalho
240	{
241	    public static string Tipo => "notificar-premio-revogado";
242	}
243	
244	// No worker: as notificações da contestação e da revogação (produto.md 8), uma por prêmio e
245	// tipo. A de decisão só sai se a contestação estiver decidida; as outras, se o prêmio ainda
246	// existir.
247	public sealed class NotificarContestacaoHandler(
248	    IPremioParticipacaoRepository premios,
249	    INotificacaoRepository notificacoes,
250	    IUnitOfWork unitOfWork,
251	    TimeProvider relogio)
252	    : ITrabalhoHandler<NotificarContestacaoAberta>, ITrabalhoHandler<NotificarDecisaoDeContestacao>, ITrabalhoHandler<NotificarPremioRevogado>
253	{
254	    public Task ExecutarAsync(NotificarContestacaoAberta carga, CancellationToken cancellationToken)
255	    {
256	        ArgumentNullException.ThrowIfNull(carga);
257	        return NotificarAsync(carga.PremioId, TipoDeNotificacao.ContestacaoAberta, Notificacao.ContestacaoAberta, cancellationToken);
258	    }
259	
260	    public Task ExecutarAsync(NotificarDecisaoDeContestacao carga, CancellationToken cancellationToken)
261	    {
262	        ArgumentNullException.ThrowIfNull(carga);
263	        return NotificarAsync(carga.PremioId, TipoDeNotificacao.DecisaoDeContestacao, Notificacao.DecisaoDeContestacao, cancellationToken);
264	    }
265	
266	    public Task ExecutarAsync(NotificarPremioRevogado carga, CancellationToken cancellationToken)
267	    {
268	        ArgumentNullException.ThrowIfNull(carga);
269	        return NotificarAsync(carga.PremioId, TipoDeNotificacao.PremioRevogado, Notificacao.PremioRevogado, cancellationToken);
270	    }
271	
272	    private async Task NotificarAsync(
273	        Guid premioId, TipoDeNotificacao tipo, Func<PremioParticipacao, DateTimeOffset, Notificacao> criar, CancellationToken cancellationToken)
274	    {
275	        var premio = await premios.BuscarAsync(premioId, cancellationToken);
276	        if (premio is null || await notificacoes.ExisteAsync(premio.AlunoId, tipo, premio.Id, cancellationToken))
277	        {
278	            return;
279	        }
280	
281	        notificacoes.Adicionar(criar(premio, relogio.GetUtcNow()));
282	        await unitOfWork.SalvarAsync(cancellationToken);
283	    }
284	}
