14	// Curtida, comentário e seguir (produto.md 6.1 e 6.3). Curtir, descurtir, seguir e deixar
15	// de seguir são idempotentes: o app repete o pedido sem medo.
16	internal static class SocialEndpoints
17	{
18	    // Página de comentários: cabe numa tela e meia de celular.
19	    public const int ComentariosPorPagina = 20;
20	
21	    public static IEndpointRouteBuilder MapSocialEndpoints(this IEndpointRouteBuilder v1)
22	    {
23	        var post = v1.MapGroup("/posts/{postId:guid}").WithTags("Posts");
24	
25	        post.MapPut("/curtida", CurtirAsync)
26	            .WithName("CurtirPost")
27	            .ProducesProblem(StatusCodes.Status403Forbidden)
28	            .ProducesProblem(StatusCodes.Status404NotFound);
29	
30	        post.MapDelete("/curtida", DescurtirAsync)
31	            .WithName("DescurtirPost")
32	            .ProducesProblem(StatusCodes.Status403Forbidden)
33	            .ProducesProblem(StatusCodes.Status404NotFound);
34	
35	        post.MapGet("/comentarios", ComentariosAsync)
36	            .WithName("GetComentarios")
37	            .ProducesProblem(StatusCodes.Status400BadRequest)
38	            .ProducesProblem(StatusCodes.Status404NotFound);
39	
40	        post.MapPost("/comentarios", ComentarAsync)
41	            .WithName("Comentar")
42	            .ProducesValidationProblem()
43	            .ProducesProblem(StatusCodes.Status403Forbidden)
44	            .ProducesProblem(StatusCodes.Status404NotFound);
45	
46	        post.MapDelete("/comentarios/{comentarioId:guid}", RemoverComentarioAsync)
47	            .WithName("RemoverComentario")
48	            .ProducesProblem(StatusCodes.Status403Forbidden)
49	            .ProducesProblem(StatusCodes.Status404NotFound);
50	
51	        var seguindo = v1.MapGroup("/seguindo").WithTags("Seguir");
52	
53	        seguindo.MapPut("/{usuarioId:guid}", SeguirAsync)
54	            .WithName("Seguir")
55	            .ProducesProblem(StatusCodes.Status403Forbidden)
56	            .ProducesProblem(StatusCodes.Status404NotFound);
57	
58	        seguindo.MapDelete("/{usuarioId:guid}", DeixarDeSeguirAsync)
59	            .WithName("DeixarDeSeguir");
60	
61	        return v1;
62	    }
63	
64	    private static async Task<Ok<CurtidasResponse>> CurtirAsync(
65	        Guid postId, ClaimsPrincipal principal, CurtidaHandler handler, CancellationToken cancellationToken) =>
66	        TypedResults.Ok(CurtidasResponse.De(await handler.CurtirAsync(PostEndpoints.UsuarioId(principal), postId, cancellationToken)));
67	
68	    private static async Task<Ok<CurtidasResponse>> DescurtirAsync(
69	        Guid postId, ClaimsPrincipal principal, CurtidaHandler handler, CancellationToken cancellationToken) =>
70	        TypedResults.Ok(CurtidasResponse.De(await handler.DescurtirAsync(PostEndpoints.UsuarioId(principal), postId, cancellationToken)));
71	
72	    // O post removido não mostra comentário: 404, como o próprio post.
73	    private static async Task<Ok<PaginaDeComentariosResponse>> ComentariosAsync(
74	        Guid postId,
75	        string? cursor,
76	        ClaimsPrincipal principal,
77	        IConsultaDePosts consultaDePosts,
78	        IConsultaSocial consulta,
79	        IArmazenamentoDeFotos armazenamento,
80	        CancellationToken cancellationToken)
81	    {
82	        var posicao = CursorDeTempo.Ler(cursor);
83	        _ = await consultaDePosts.PostAsync(postId, PostEndpoints.UsuarioId(principal), cancellationToken)
84	            ?? throw new RecusaException(
