1	using Maxx.Application.Fila;
2	using Microsoft.AspNetCore.Http.HttpResults;
3	using Microsoft.Extensions.Diagnostics.HealthChecks;
4	
5	namespace Maxx.Api.Health;
6	
7	internal static class HealthEndpoints
8	{
9	    // Infraestrutura, não contrato: fica fora de /v1.
10	    public static IEndpointRouteBuilder MapHealthEndpoints(this IEndpointRouteBuilder routes)
11	    {
12	        routes.MapGet("/health", GetHealth)
13	            .WithName("GetHealth")
14	            .WithTags("Health");
15	
16	        routes.MapGet("/ready", GetReadyAsync)
17	            .WithName("GetReady")
18	            .WithTags("Health")
19	            .ProducesProblem(StatusCodes.Status503ServiceUnavailable);
20	
21	        // Para o monitor de fora (docs/operacao.md): 503 com o mesmo corpo quando há problema.
22	        // Só idades, contagens e códigos: nada de carga de trabalho, erro ou dado de alguém.
23	        routes.MapGet("/health/worker", GetWorkerAsync)
24	            .WithName("GetSaudeDoWorker")
25	            .WithTags("Health")
26	            .Produces<SaudeDoWorkerResponse>(StatusCodes.Status503ServiceUnavailable);
27	
28	        return routes;
29	    }
30	
31	    // Liveness: o processo responde. Não toca no banco.
32	    private static Ok<HealthResponse> GetHealth() => TypedResults.Ok(HealthResponse.Ok);
33	
34	    private static async Task<Results<Ok<HealthResponse>, ProblemHttpResult>> GetReadyAsync(
35	        HealthCheckService healthChecks,
36	        CancellationToken cancellationToken)
37	    {
38	        var report = await healthChecks.CheckHealthAsync(cancellationToken);
39	
40	        if (report.Status != HealthStatus.Healthy)
41	        {
42	            return TypedResults.Problem(
43	                statusCode: StatusCodes.Status503ServiceUnavailable,
44	                title: "Serviço indisponível.");
45	        }
46	
47	        return TypedResults.Ok(HealthResponse.Ok);
48	    }
49	
50	    private static async Task<Results<Ok<SaudeDoWorkerResponse>, JsonHttpResult<SaudeDoWorkerResponse>>> GetWorkerAsync(
51	        IConsultaDaSaudeDoWorker consulta,
52	        CancellationToken cancellationToken)
53	    {
54	        var saude = await consulta.ConsultarAsync(cancellationToken);
55	        var resposta = new SaudeDoWorkerResponse(
56	            saude.Saudavel ? "ok" : "problema",
57	            Segundos(saude.DesdeOBatimento),
58	            Segundos(saude.EsperaDoMaisAntigo),
59	            saude.Disponiveis,
60	            saude.FalhosNaJanela,
61	            saude.Problemas);
62	
63	        return saude.Saudavel
64	            ? TypedResults.Ok(resposta)
65	            : TypedResults.Json(resposta, statusCode: StatusCodes.Status503ServiceUnavailable);
66	    }
67	
68	    private static int? Segundos(TimeSpan? duracao) => duracao is { } valor ? (int)Math.Floor(valor.TotalSeconds) : null;
69	}
70	
71	public sealed record HealthResponse(string Status)
72	{
73	    public static HealthResponse Ok { get; } = new("ok");
74	}
75	
76	// Segundos inteiros; nulos quando não há batimento ou trabalho disponível.
77	public sealed record SaudeDoWorkerResponse(
78	    string Status,
79	    int? SegundosDesdeOBatimento,
80	    int? SegundosDeEsperaNaFila,
81	    int Disponiveis,
82	    int FalhosEm24h,
83	    IReadOnlyList<string> Problemas);
