87	    // $argon2id$v=19$m=19456,t=2,p=1$<sal>$<hash>
88	    private static bool TryLer(
89	        string? hash, out int memoria, out int iteracoes, out int paralelismo, out byte[] sal, out byte[] esperado)
90	    {
91	        memoria = iteracoes = paralelismo = 0;
92	        sal = esperado = [];
93	
94	        if (hash is null || !hash.StartsWith(_prefixo, StringComparison.Ordinal))
95	        {
96	            return false;
97	        }
98	
99	        var partes = hash[_prefixo.Length..].Split('$');
100	        if (partes.Length != 3)
101	        {
102	            return false;
103	        }
104	
105	        var parametros = partes[0].Split(',');
106	        if (parametros.Length != 3
107	            || !TryParametro(parametros[0], "m=", out memoria)
108	            || !TryParametro(parametros[1], "t=", out iteracoes)
109	            || !TryParametro(parametros[2], "p=", out paralelismo))
110	        {
111	            return false;
112	        }
113	
114	        return TryBase64(partes[1], out sal) && TryBase64(partes[2], out esperado) && sal.Length > 0 && esperado.Length > 0;
115	    }
