117	    private static bool TryParametro(string texto, string nome, out int valor)
118	    {
119	        valor = 0;
120	        return texto.StartsWith(nome, StringComparison.Ordinal)
121	            && int.TryParse(texto.AsSpan(nome.Length), NumberStyles.None, CultureInfo.InvariantCulture, out valor)
122	            && valor > 0;
123	    }
