127	    private static bool TryBase64(string texto, out byte[] bytes)
128	    {
129	        var comPreenchimento = texto.PadRight(texto.Length + ((4 - (texto.Length % 4)) % 4), '=');
130	        bytes = new byte[comPreenchimento.Length];
131	        if (Convert.TryFromBase64String(comPreenchimento, bytes, out var escritos))
132	        {
133	            bytes = bytes[..escritos];
134	            return true;
135	        }
136	
137	        bytes = [];
138	        return false;
139	    }
